begin;
do $$
declare actor text:='guidelines-test-'||gen_random_uuid()||'@example.invalid';req jsonb;r jsonb;rev bigint;rejected boolean;
 app_id text:='APP-GUIDELINES-TEST-'||gen_random_uuid();code text:='1616-GUIDELINES-'||upper(gen_random_uuid()::text);player_key text;summary jsonb;
begin
 if has_function_privilege('anon','nova_evidence_private.alliance_guidelines_store(text,jsonb)','execute') or has_table_privilege('authenticated','nova_evidence_private.alliance_guidelines','select') then raise exception 'Public guideline storage access';end if;
 insert into nova_evidence_private.hub_staff(email,role,alliances,status,updated_by) values(actor,'r4','["NvSP"]','active',actor);
 req:=jsonb_build_object('staffEmail',actor,'kind','alliance-guidelines','alliance','NvSP','introduction','Test introduction','guidelines','Published rules','translations',(select jsonb_object_agg(lang,jsonb_build_object('introduction','Test introduction '||lang,'guidelines','Published rules '||lang)) from unnest(array['es','pt','fr','ar','vi','ko','de']) lang));
 r:=public.nova_hub_store('hub-content-list',req);
 if jsonb_array_length(r)<>1 or r#>>'{0,alliance}'<>'NvSP' then raise exception 'Alliance list scope';end if;
 rev:=(r#>>'{0,revision}')::bigint;
 rejected:=false;begin perform public.nova_hub_store('hub-content-save',req||jsonb_build_object('alliance','NvEM','revision',0));exception when others then rejected:=true;end;
 if not rejected then raise exception 'Cross-alliance save permitted';end if;
 r:=public.nova_hub_store('hub-content-save',req||jsonb_build_object('revision',rev,'publish',true));
 if (r->>'revision')::bigint<>rev+1 then raise exception 'Publish revision';end if;
 r:=public.nova_hub_store('hub-content-save',req||jsonb_build_object('revision',rev+1,'guidelines','PRIVATE DRAFT','publish',false));
 if r#>>'{published,guidelines}'<>'Published rules' then raise exception 'Draft replaced publication';end if;
 rejected:=false;begin perform public.nova_hub_store('hub-content-save',req||jsonb_build_object('revision',rev));exception when others then rejected:=true;end;
 if not rejected then raise exception 'Stale revision accepted';end if;
 rejected:=false;begin perform public.nova_hub_store('hub-content-save',req||jsonb_build_object('revision',rev+2,'publish',true,'guidelines',''));exception when others then rejected:=true;end;
 if not rejected then raise exception 'Empty publication accepted';end if;
 rejected:=false;begin perform public.nova_hub_store('hub-content-save',req||jsonb_build_object('revision',rev+2,'publish',true,'translations','{}'::jsonb));exception when others then rejected:=true;end;
 if not rejected then raise exception 'Incomplete translations published';end if;
 update nova_evidence_private.hub_staff set status='revoked' where email=actor;
 rejected:=false;begin perform public.nova_hub_store('hub-content-list',req);exception when others then rejected:=true;end;
 if not rejected then raise exception 'Revoked leader read allowed';end if;
 insert into transfer_private.applications(id,code_hash,payload) values(app_id,encode(sha256(convert_to(code,'UTF8')),'hex'),jsonb_build_object('applicationId',app_id,'username','Fictional guidelines applicant','confirmationCode',code));
 select key into player_key from transfer_private.portal_records where kind='players' and payload->>'applicationId'=app_id limit 1;
 if player_key is null then raise exception 'Synthetic application not linked';end if;
 update transfer_private.portal_records set payload=payload||jsonb_build_object('status','Approved') where kind='players' and key=player_key;
 update transfer_private.portal_records set payload=jsonb_set(payload,array['data','assignments',player_key],'"NvSP"'::jsonb,true) where kind='shared' and key='transferOrganization';
 summary:=public.transfer_application_status(jsonb_build_object('requestType','application.status','confirmationCode',code));
 if summary#>>'{status,allianceGuidelines,guidelines}'<>'Published rules' or summary::text like '%PRIVATE DRAFT%' or summary::text like '%'||actor||'%' then raise exception 'Applicant publication boundary';end if;
 if summary#>>'{status,allianceGuidelines,translations,de,guidelines}'<>'Published rules de' or summary#>>'{status,allianceGuidelines,translations,ar,guidelines}'<>'Published rules ar' then raise exception 'Published translations missing';end if;
 update transfer_private.portal_records set payload=payload||jsonb_build_object('status','Declined') where kind='players' and key=player_key;
 summary:=public.transfer_application_status(jsonb_build_object('requestType','application.status','confirmationCode',code));
 if summary#>>'{status,allianceGuidelines}' is not null then raise exception 'Rejected applicant exposed assignment guidelines';end if;
end;
$$;
select 'PASS: own-alliance editing, cross-alliance rejection, published-only applicant content, private drafts, conflict protection, blank publication rejection, revoked access, rejected application; fixtures rolled back' as verification;
rollback;
